import {energy02Data as data} from './energy02-data.js?v=20261027-energy02';
import {developmentPaths} from './development-data.js?v=20261026-development01';
import {energy01Scene} from './model-energy01.js?v=20261027-energy01';
import {managementScene} from './model-ecosystems4.js?v=20261024-ecosystems04';
export {energy02Data} from './energy02-data.js?v=20261027-energy02';
export const energy02Views={
 'dev-energy2-global-mix':[['factors','What shapes a mix?'],['map','Locate the profiles'],['india','India · 2023'],['us','USA · 2024']],
 'dev-energy2-demand-change':[['history','A century of change'],['drivers','Services and efficiency'],['recent','Demand growth'],['future','Future population']],
 'dev-energy2-nonrenewable-development':[['coal','Coal access'],['oil','Offshore oil'],['gas','Gas supply'],['uranium','Uranium fuel cycle'],['tradeoffs','People and environment']],
 'dev-energy2-renewable-development':[['hep','Water to electricity'],['solar','Light to electricity'],['wind','Wind to electricity'],['compare','Develop the right site']],
 'dev-energy2-fracking':[['drill','Reach the rock'],['fracture','Open pathways'],['produce','Recover existing gas'],['risks','Evaluate the risks']]
};
export const energy02Requirements=Object.fromEntries(Object.entries(energy02Views).map(([k,v])=>[k,v.map(x=>x[0])]));
export const energy02Animated=(k,v)=>k==='dev-energy2-demand-change'?v==='drivers':k==='dev-energy2-nonrenewable-development'?v!=='tradeoffs':k==='dev-energy2-renewable-development'?v!=='compare':k==='dev-energy2-fracking'?v!=='risks':false;
export const serviceDemand=(services,intensity)=>services*intensity;
export const indexedDemand=(base,rate)=>base*(1+rate/100);
const T=(x,y,s,z=12)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#c2d3cd',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,c='#edb396',r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#f1e4ce"/>`;
const box=(x,y,w,a,b)=>`<rect x="${x}" y="${y}" width="${w}" height="${b?64:40}" rx="10" fill="#35566b" stroke="#a6c1c8"/>`+T(x+12,y+24,a)+(b?T(x+12,y+47,b,11):'');
const title=s=>T(20,30,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,t)=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`;
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${cap}</caption><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
const sources={mix:link(data.profiles[0].source,'EIA India: 2023 profile, published 6 February 2025')+' · '+link(data.profiles[1].source,'EIA USA: preliminary 2024 snapshot')+'. Primary consumption shares, rounded. Different years and account conventions; not a controlled or exact matched-year comparison. A rounded zero does not establish no use.',demand:link(data.growth.source,'IEA Global Energy Review 2026')+'. Published 20 April 2026; CC BY4.0. Revised2024 growth2.0%,2025 growth1.3%. Percent annual global energy demand growth, not percentage points of fuel share. Solar’s contribution to growth is not its total share.',history:link(data.population.source,'UN: historical population milestones')+' · '+link('https://www.eia.gov/energyexplained/us-energy-facts/','EIA: century-scale fuel and technology context')+'. Rounded population estimates and a conceptual global process history; not a measured annual global-energy series. Dates are historical context, not a forecast.',coal:link('https://www.eia.gov/energyexplained/coal/mining-and-transportation.php','EIA: coal access and transport')+'. Surface and underground access are schematic alternatives, not a real mine, measured excavation or universal depth threshold.',oil:link('https://www.eia.gov/energyexplained/oil-and-petroleum-products/oil-and-the-environment.php','EIA: oil production and impacts')+'. Symbolic offshore supply route, not a real field, flow rate or spill prediction.',uranium:link('https://www.eia.gov/energyexplained/nuclear/nuclear-power-and-the-environment.php','EIA: nuclear fuel-cycle impacts and waste')+'. Fission is not fossil combustion. Symbolic stages do not show reactor engineering, doses, waste volumes or disposal lifetimes.',renew:link('https://www.eia.gov/energyexplained/hydropower/hydropower-and-the-environment.php','EIA: hydropower effects')+' · '+link('https://www.eia.gov/energyexplained/solar/solar-energy-and-the-environment.php','EIA: solar development')+'. Water/light flows are illustrative, not calibrated output or a named dam/panel. Operating and lifecycle effects differ.',frack:link('https://www.eia.gov/energyexplained/natural-gas/where-our-natural-gas-comes-from.php','EIA: horizontal drilling and stimulation')+' · '+link('https://www.usgs.gov/faqs/does-production-oil-and-gas-shales-cause-earthquakes-if-so-how-are-earthquakes-related-these','USGS: induced seismicity and separate disposal injection')+' · '+link('https://www.eia.gov/energyexplained/natural-gas/natural-gas-and-the-environment.php','EIA: gas environmental effects')+'. Symbolic geometry, depth and timing; not actual fracture extent, well-integrity assurance, measured leak risk or current UK policy.'};
const source=k=>`<p class="geo-caption">${sources[k]}</p>`;
export function energy02Evidence(k='india'){
 if(k==='projection')return managementScene('eco-population-projections','projection',0);
 if(k==='growth'){let b=title('WORLD ENERGY DEMAND · ANNUAL GROWTH')+T(20,54,'IEA2026 release · percent per year · zero baseline',11);for(const[i,[year,v]]of data.growth.rates.entries()){const y=110+i*95;b+=T(20,y,String(year),15)+`<rect x="90" y="${y-21}" width="${v*135}" height="32" rx="4" fill="${i?'#edb396':'#aec4b0'}"/>`+T(103+v*135,y+1,v.toFixed(1)+'%',14);}b+=line('M90 278H360')+T(86,300,'0%',11)+T(214,300,'1%',11)+T(350,300,'2%',11);return fig(b,'Two reported annual percentage growth rates for global energy demand. Read the sign, year and denominator; this is not the level of energy consumption.')+source('demand')+table('IEA2026 edition: annual global demand growth',['Year','Percent'],data.growth.rates);}
 const p=data.profiles[k==='us'?1:0];let b=title(p.country.toUpperCase()+' · PRIMARY CONSUMPTION · '+p.year)+T(20,53,'Percent of total · published rounded categories',11);for(const[i,[n,v]]of p.rows.entries()){const y=86+i*36;b+=T(20,y,n,11)+`<rect x="185" y="${y-13}" width="${v*3}" height="20" rx="3" fill="${['#e5c9a5','#96bcb3','#c1cda6','#b2b7d0','#e2ad95','#adc7c0'][i]}"/>`+T(195+v*3,y+2,v+'%',12);}b+=T(20,328,p.country==='India'?'Hydro rounds to0%; it is not absent.':'Preliminary2024 snapshot; read its source vintage.',11);return fig(b,p.country+' '+p.year+' primary-consumption profile. Source grouping and rounding retained; the other country profile is a different year and account context.')+source('mix')+table(p.country+' '+p.year+' rounded primary consumption shares',['Category','Percent'],p.rows);
}
export function energy02Scene(k,v,t=0){if(!energy02Views[k])return '';if(!energy02Requirements[k].includes(v))v=energy02Requirements[k][0];t=energy02Animated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s='mix';
 if(k==='dev-energy2-global-mix'){
 if(['india','us'].includes(v))return energy02Evidence(v);
 if(v==='map'){b=title('LOCATE THE DATED COUNTRY PROFILES')+T(20,52,'North ↑ · actual generalised world outlines',11);for(const p of developmentPaths)b+=`<path d="${p.d}" fill="${['IND','USA'].includes(p.code)?'#b9c9ac':'#6e8e8c'}" stroke="#234355" stroke-width="0.5"/>`;for(const[n,lon,lat]of [['USA2024',-100,40],['India2023',79,22]]){const x=20+(lon+180)/360*400,y=55+(85-lat)/145*200;b+=dot(x,y)+T(x+10,y-8,n,11);}b+=T(20,292,'Country profiles, not complete global resource deposits.',11)+T(20,325,'Resource availability + demand + access + investment',11);c='Public-domain Natural Earth country geometry with approximate locators. This is a selected country-profile map, not a complete energy-resource distribution or a matched-year experiment.';}
 else{b=title('FOUR CONNECTED INFLUENCES')+box(20,65,190,'Population / services','How much demand?')+box(230,65,190,'Wealth / technology','What can be financed?')+box(20,190,190,'Resource availability','Geology / climate / imports')+box(230,190,190,'Infrastructure / choices','Grids / policy / existing plant')+line('M115 138V182M325 138V182M208 98H222M208 223H222')+T(20,326,'No single factor fixes one national fuel mix.',11);c='A causal comparison framework. More people can increase demand without selecting one particular fuel; resource presence alone does not guarantee access.';}
 }
 if(k==='dev-energy2-demand-change'){
 if(v==='recent')return energy02Evidence('growth');if(v==='future')return energy02Evidence('projection');s=v==='history'?'history':'demand';
 if(v==='history'){b=title('A CENTURY OF SERVICES AND SUPPLY CHANGE')+line('M35 75V295','#a8c4c6',3)+dot(35,90)+dot(35,180)+dot(35,270)+T(58,88,'1920s–1940s: industry / motor transport',11)+T(58,115,'Oil use expands; electricity networks grow',11)+T(58,178,'Post-war: wider services and production',11)+T(58,205,'Gas networks / nuclear / larger grids',11)+T(58,268,'Recent decades: efficiency and new supply',11)+T(58,295,'Wind / PV / digital and electric services',11)+T(20,331,'UN population milestones:1927≈2bn;1974≈4bn;2022≈8bn',10);c='A conceptual historical sequence with rounded population milestones. It does not imply uniform growth, fixed use per person or an annual measured global-energy series.';}
 else{const total=serviceDemand(20+10*t,2-.5*t);b=title('EFFICIENCY AND SERVICE USE CAN CHANGE TOGETHER')+box(20,65,190,'Services:20 → 30','Illustrative demand for services')+box(230,65,190,'Energy/service:2 → 1.5','Efficiency improves')+`<rect x="40" y="190" width="360" height="54" rx="6" fill="#2a4b60"/><rect x="40" y="190" width="${total*7}" height="54" rx="6" fill="#b0c6b1"/>`+T(55,225,'Total energy: '+total.toFixed(1)+' units',18)+T(20,285,'Start20×2=40 · End30×1.5=45',15)+T(20,328,'Invented teaching units; not global measured demand.',10);c='An invented comparison: efficiency improves but more services can offset the saving. Intermediate stages interpolate teaching inputs; this is not an economic forecast or actual time series.';}
 }
 if(k==='dev-energy2-nonrenewable-development'){
 if(v==='gas')return energy01Scene('dev-energy-natural-gas','supply',t);
 if(v==='coal'){s='coal';b=title('COAL · SURFACE OR UNDERGROUND ACCESS')+`<path d="M20 120H420V300H20Z" fill="#7b8f88"/><path d="M20 225H420V250H20Z" fill="#1a2f3e"/><path d="M35 120H165L120 225H35Z" fill="#b0b79c"/>`+line('M300 120V237H180','#dfc8aa',8)+dot(300,120+117*t)+dot(300-120*t,237)+T(37,86,'Overburden removed',11)+T(270,86,'Shaft + tunnel',11)+T(43,243,'Coal seam',11)+T(20,330,'Different access methods; transport and restoration still matter.',10);c='Surface access at left and underground shaft/tunnel at right. Moving tokens represent extraction, not mine workers, safety conditions or a measured transport rate.';}
 else if(v==='oil'){s='oil';b=title('OFFSHORE OIL · BUILD A SUPPLY CHAIN')+`<rect x="20" y="130" width="400" height="70" fill="#467b90"/><rect x="20" y="200" width="400" height="100" fill="#7c918b"/><ellipse cx="130" cy="265" rx="65" ry="23" fill="#1b303d"/>`+line('M95 125V70H165V125M130 200V85M130 265V95H340','#dfc4a3',5)+dot(130,265-170*t)+dot(130+210*t,95)+box(265,35,155,'Transport / refinery','Investment / staff')+T(24,177,'Sea',12)+T(84,270,'Oil deposit',12)+T(20,330,'Fuel/services and jobs; spills, emissions and habitat risks.',10);c='A conceptual offshore well-to-processing route, not a real rig design, deposit size, spill probability or extraction rate.';}
 else if(v==='uranium'){s='uranium';b=title('URANIUM · A FINITE NUCLEAR FUEL CYCLE')+box(20,65,180,'Mine / process','Make suitable reactor fuel')+box(240,65,180,'Fission / heat / power','No fossil combustion here')+box(240,235,180,'Manage used fuel','Storage / disposal / safety')+line('M200 100H233M330 138V228')+dot(200+33*t,100)+dot(330,138+90*t)+T(20,330,'No instant fuel recycling or waste disappearance is shown.',10);c='Symbolic fuel-cycle stages. Uranium is finite; reactor operation differs from fossil burning, while mining, construction and waste responsibilities remain.';}
 else{s='uranium';b=title('EVALUATE WHO GAINS AND WHO BEARS COSTS')+box(20,65,400,'Benefits','Energy services / jobs / revenue / useful infrastructure')+box(20,155,400,'Costs and risks','Land / emissions / safety / waste / capital and fuel costs')+box(20,245,400,'Evidence','Affected groups / duration / safeguards / alternatives');c='A cross-resource decision framework, not a claim that coal, oil, gas and uranium have identical impacts or that all residents gain equally.';}
 }
 if(k==='dev-energy2-renewable-development'){
 if(v==='wind')return energy01Scene('dev-energy-wind','rotor',t);s='renew';
 if(v==='hep'){b=title('RESERVOIR HEP · WATER → TURBINE → GENERATOR')+`<path d="M20 145H225V270H20Z" fill="#538ca0"/><path d="M225 95L265 280H215Z" fill="#9aa99d"/>`+line('M70 190H233L320 255H410','#bed6d4',9)+dot(70+163*Math.min(t*2,1),190)+dot(233+87*t,190+65*t)+`<g transform="translate(320 255) rotate(${t*360})">${[0,90,180,270].map(a=>`<path transform="rotate(${a})" d="M0 0L-8-25Q15-25 13-8Z" fill="#edb699"/>`).join('')}</g>`+box(275,65,145,'Generator','Grid connection')+line('M320 225V138')+T(28,170,'Stored water',12)+T(20,329,'Replenishment depends on catchment flow; geometry symbolic.',10);c='Illustrative reservoir, penstock, turbine and generator. Water is released rather than burned; dam flows, head and output are not calibrated. Impacts on river habitats and communities need assessment.';}
 else if(v==='solar'){b=title('SOLAR PV · LIGHT → CELLS → ELECTRICITY')+`<circle cx="72" cy="90" r="27" fill="#e8c99b"/>`+Array.from({length:3},(_,i)=>line(`M${85+i*23} ${110+i*8}l80 60`,'#e8c99b',3)+dot(100+i*22+65*t,120+i*8+45*t,'#ebd7a9',3)).join('')+`<path d="M90 190L275 165 320 260 125 280Z" fill="#638899" stroke="#b4ced1" stroke-width="2"/>`+Array.from({length:4},(_,i)=>line(`M${120+i*40} ${186-i*5}l35 83`,'#b7ced1',1)).join('')+line('M150 230L285 210M137 210L292 189','#b7ced1',1)+line('M310 240H400')+dot(320+80*t,240,'#b7cfb9')+T(302,301,'Inverter / grid',12)+T(20,330,'PV cells convert light directly; no turbine inside a cell.',10);c='A schematic PV panel and electric connection. Light tokens are not individual measured photons or a power forecast; daylight, cloud, materials and grid capacity affect development.';}
 else{b=title('DEVELOP A SYSTEM THAT FITS THE SITE')+box(20,65,190,'Physical conditions','Water / head / wind / light')+box(230,65,190,'Connections / investment','Grid / maintenance / storage')+box(20,190,190,'People and ecosystems','Land / flow / livelihoods')+box(230,190,190,'Delivered service','Cost / variability / benefits')+T(20,327,'Pumped storage uses earlier electricity; it is not new energy.',10);c='Static appraisal of HEP, wind and solar development. Source renewal does not remove variability, lifecycle costs or community and ecological tradeoffs.';}
 }
 if(k==='dev-energy2-fracking'){
 s='frack';if(v==='risks'){b=title('SUPPLY GAINS ARE CONDITIONAL')+box(20,65,190,'Potential benefit','More recoverable gas / jobs')+box(230,65,190,'Well and surface controls','Integrity / fluid containment')+box(20,190,190,'Risks and monitoring','Methane / water / seismicity')+box(230,190,190,'Economic limits','Costs / decline / markets')+T(20,326,'Deep wastewater injection is a separate operation.',11);c='A risk-and-benefit framework. Fracturing and separate wastewater disposal injection can both induce seismicity; this is not a guarantee of safety, cheap fuel or policy permission.';}
 else{b=title(v==='drill'?'REACH A LOW-PERMEABILITY TARGET':v==='fracture'?'PRESSURE + PROPPANT OPEN FLOW PATHS':'EXISTING GAS MOVES BACK TO THE WELL')+`<rect x="20" y="85" width="400" height="40" fill="#6d9caa"/><rect x="20" y="125" width="400" height="85" fill="#88988e"/><rect x="20" y="210" width="400" height="90" fill="#4e707a"/>`+T(235,109,'Shallow groundwater',11)+T(245,194,'Other formations',11)+T(245,291,'Target shale',11)+line('M103 70V200M117 70V200','#d3d4c1',3)+line('M110 65V250Q110 260 130 260H380','#d4c0a4',7);
 if(v==='drill'){const x=t<.5?110:130+(t-.5)*500,y=t<.5?65+t*390:260;b+=dot(x,y,'#f0d0a4',7)+T(20,326,'Down, then along the target · casing/cement simplified',10);c='Symbolic down-and-horizontal drilling. The well shown is a schematic reference and the moving marker indicates progress; geometry is not a drilling depth or well-integrity assurance.';}
 else{for(const x of [185,255,325]){const a=v==='fracture'?10+25*t:35;b+=line(`M${x} 260l-12-${a}m12 ${a}l15 ${a*.65}`,'#bdd9d8',2);for(let j=0;j<3;j++)b+=dot(x-3-j*3,250-j*8,'#e6c69e',2);}if(v==='fracture'){b+=dot(110,65+185*t,'#aad4df')+dot(130+250*t,260,'#aad4df')+T(20,326,'Fluid opens fractures; proppant helps paths stay open.',10);c='Illustrative stimulation within a target formation. Connected paths increase permeability; proppant is not a new fuel. Fracture extent, pressure and groundwater protection are not measured here.';}else{b+=dot(380-250*t,260,'#efb39b')+dot(110,250-185*t,'#efb39b')+T(20,56,'Surface collection and fluid handling',11)+T(20,326,'Gas already existed; flowback/produced water need control.',10);c='Conceptual gas movement along newly connected paths to the well and surface handling. It does not create methane or model extraction rate, decline, flowback composition or disposal injection.';}}
 }
 }
 return fig(b,c)+source(s);
}
